import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Fused LogSumExp + ReLU CUDA kernel
lse_relu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void lse_relu_kernel(const float* in, float* out,
                                int B, int C, int D, int H, int W) {
    int index = blockDim.x * blockIdx.x + threadIdx.x;
    int total = B * D * H * W;
    if (index < total) {
        int w = index % W;
        int h = (index / W) % H;
        int d = (index / (W*H)) % D;
        int b = index / (W*H*D);

        // Compute logsumexp across channel dimension
        float max_val = -FLT_MAX;
        for (int c = 0; c < C; c++) {
            int c_offset = (((b * C + c) * D + d) * H + h) * W + w;
            float val = in[c_offset];
            if (val > max_val) {
                max_val = val;
            }
        }
        float sum_exp = 0.0f;
        for (int c = 0; c < C; c++) {
            int c_offset = (((b * C + c) * D + d) * H + h) * W + w;
            sum_exp += expf(in[c_offset] - max_val);
        }
        float lse = logf(sum_exp) + max_val;
        // Apply ReLU
        lse = fmaxf(lse, 0.0f);

        // Store result in output, shape is [B, 1, D, H, W]
        int out_offset = (((b * 1 + 0) * D + d) * H + h) * W + w;
        out[out_offset] = lse;
    }
}

torch::Tensor lse_relu_forward(torch::Tensor x) {
    // x is expected to be 5D: [B, C, D, H, W]
    TORCH_CHECK(x.dim() == 5, "Input must be a 5D tensor");
    auto B = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    auto out_sizes = std::vector<int64_t>{B, 1, D, H, W};
    auto out = torch::zeros(out_sizes, x.options());

    int total = B * D * H * W;
    const int threads = 256;
    int blocks = (total + threads - 1) / threads;

    lse_relu_kernel<<<blocks, threads>>>(x.data_ptr<float>(),
                                         out.data_ptr<float>(),
                                         B, C, D, H, W);
    return out;
}
"""

lse_relu_cpp_source = r"""
torch::Tensor lse_relu_forward(torch::Tensor x);
"""

# Load and compile the fused operator
lse_relu = load_inline(
    name="lse_relu",
    cpp_sources=lse_relu_cpp_source,
    cuda_sources=lse_relu_source,
    functions=["lse_relu_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D convolution, max pooling, and fused LogSumExp+ReLU.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.max_pool = nn.MaxPool3d(kernel_size=2, stride=2)

    def forward(self, x):
        x = self.conv(x)
        x = self.max_pool(x)
        # Fused logsumexp + ReLU along dim=1
        x = lse_relu.lse_relu_forward(x)
        return x

